func TestNotificationDeliveryHistoryTiesBreakOnID(t *testing.T) {
	st := openTestStore(t)
	ctx := context.Background()

	ids := []string{}
	for i := 0; i < 3; i++ {
		saved, err := st.CreateDeliveryRecord(ctx, mustRecord(t, delivery.RecordInput{
